function isAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (e) {
    // ESRCH => no such process. EPERM => alive but not ours (treat as alive).
    return (e as NodeJS.ErrnoException).code === "EPERM";
  }
}

