private cancelPendingCall(
  id: string,
  pending: PendingRequest,
  child: ChildProcess,
  error: NativeToolHostError,
): void {
  if (pending.callerSettled) return;
  pending.callerSettled = true;
  clearTimeout(pending.timer);
  pending.removeAbortListener?.();
  pending.reject(error);
  try {
    if (child.connected) child.send({ type: "cancel", id });
  } catch {
    // The grace timer below is the authoritative containment boundary.
  }
  pending.cancellationTimer = setTimeout(() => {
    if (this.pending.get(id) !== pending || this.child !== child) return;
    this.pending.delete(id);
    child.kill();
    this.handleCrash(new NativeToolHostError(
      "tool_host_unresponsive",
      `Native Tool Host did not stop call ${id} within the cancellation grace period`,
      { cause: error },
    ));
  }, this.options.cancellationGraceMs ?? 250);
}

export async function stopDaemonProcess(
  pid: number,
  options: { graceMs?: number; forceKillMs?: number } = {},
): Promise<void> {
  if (!daemonPidAlive(pid)) return;
  terminateDaemonProcess(pid);
  if (await waitForProcessExit(pid, options.graceMs ?? 5_000)) return;
  forceKillDaemonProcess(pid);
  if (await waitForProcessExit(pid, options.forceKillMs ?? 2_000)) return;
  throw new Error(`Daemon process did not stop: ${pid}`);
}

function validateGracePeriod(value: number): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new Error("Attachment grace period must be a non-negative safe integer");
  }
}

export function killProcessTree(child: ChildProcess): void {
  signalProcessTree(child, "SIGKILL");
}

