export interface AttachmentRoutingDecision {
  assetId: string;
  intent: SessionInputAttachmentRecord["intent"];
  mediaType: string;
  route: "native_image" | "image_to_text_tool" | "text_inline" | "text_resource" | "blocked";
  reason?: AttachmentRoutingErrorCode;
  complete?: boolean;
  resourceUri?: string;
}

function blocked(
  code: AttachmentRoutingErrorCode,
  assetIds: string[],
  decisions: AttachmentRoutingDecision[],
): AttachmentRoutingError {
  return new AttachmentRoutingError(code, routingErrorMessage(code), assetIds, decisions);
}

function attachmentRoutingError(
  error: unknown,
): Pick<AttachmentRoutingError, "code" | "assetIds" | "decisions"> | undefined {
  if (!error || typeof error !== "object") return undefined;
  const candidate = error as Partial<AttachmentRoutingError>;
  if (
    typeof candidate.code !== "string" ||
    !Array.isArray(candidate.assetIds) ||
    !Array.isArray(candidate.decisions)
  ) {
    return undefined;
  }
  return candidate as Pick<
    AttachmentRoutingError,
    "code" | "assetIds" | "decisions"
  >;
}

